# Terraform Refactor: Dev/Prod Duplication → for_each Module

## Before State (Duplicated Blocks)

```hcl
# main.tf - BEFORE: repetitive structure
resource "aws_eks_cluster" "dev" {
  name            = "app-cluster-dev"
  role_arn        = aws_iam_role.eks_dev.arn
  version         = "1.27"
  vpc_config {
    subnet_ids = var.dev_subnet_ids
  }
}

resource "aws_eks_cluster" "prod" {
  name            = "app-cluster-prod"
  role_arn        = aws_iam_role.eks_prod.arn
  version         = "1.27"
  vpc_config {
    subnet_ids = var.prod_subnet_ids
  }
}

resource "aws_eks_node_group" "dev" {
  cluster_name    = aws_eks_cluster.dev.name
  node_role_arn   = aws_iam_role.nodes_dev.arn
  subnet_ids      = var.dev_subnet_ids
  desired_size    = 2
  instance_types  = ["t3.medium"]
}

resource "aws_eks_node_group" "prod" {
  cluster_name    = aws_eks_cluster.prod.name
  node_role_arn   = aws_iam_role.nodes_prod.arn
  subnet_ids      = var.prod_subnet_ids
  desired_size    = 4
  instance_types  = ["t3.large"]
}

# S3, RDS, IAM, ALB, secrets... all duplicated with dev/prod suffixes
```

---

## After: Refactored with for_each Module

### 1. Create the Module Structure

**`modules/environment/main.tf`**

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# EKS Cluster
resource "aws_eks_cluster" "main" {
  name            = var.cluster_name
  role_arn        = aws_iam_role.eks.arn
  version         = "1.27"
  vpc_config {
    subnet_ids = var.subnet_ids
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy
  ]
}

# EKS Node Group
resource "aws_eks_node_group" "main" {
  cluster_name    = aws_eks_cluster.main.name
  node_role_arn   = aws_iam_role.nodes.arn
  subnet_ids      = var.subnet_ids
  desired_size    = var.node_desired_size
  instance_types  = var.node_instance_types

  depends_on = [
    aws_iam_role_policy_attachment.node_policy,
    aws_iam_role_policy_attachment.node_cni_policy
  ]
}

# IAM Role for EKS Cluster
resource "aws_iam_role" "eks" {
  name               = "${var.environment}-eks-cluster-role"
  assume_role_policy = data.aws_iam_policy_document.eks_assume.json
}

data "aws_iam_policy_document" "eks_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks.name
}

# IAM Role for Nodes
resource "aws_iam_role" "nodes" {
  name               = "${var.environment}-eks-node-role"
  assume_role_policy = data.aws_iam_policy_document.node_assume.json
}

data "aws_iam_policy_document" "node_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy_attachment" "node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.nodes.name
}

resource "aws_iam_role_policy_attachment" "node_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.nodes.name
}

# S3 Bucket for Application Assets
resource "aws_s3_bucket" "assets" {
  bucket = "${var.environment}-app-assets-${var.account_id}"
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# S3 Replication (prod only)
resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.s3_replication[0].arn

  rule {
    status = "Enabled"
    destination {
      bucket       = "arn:aws:s3:::${var.environment}-app-assets-${var.account_id}-replica"
      storage_class = "STANDARD_IA"
    }
  }

  depends_on = [aws_s3_bucket_versioning.assets]
}

resource "aws_iam_role" "s3_replication" {
  count = var.enable_replication ? 1 : 0
  name  = "${var.environment}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

# RDS PostgreSQL Instance
resource "aws_db_subnet_group" "main" {
  name       = "${var.environment}-rds-subnet-group"
  subnet_ids = var.db_subnet_ids
}

resource "aws_rds_cluster" "main" {
  cluster_identifier              = "${var.environment}-db-cluster"
  engine                          = "aurora-postgresql"
  engine_version                  = "14.6"
  database_name                   = "appdb"
  master_username                 = "postgres"
  master_password                 = random_password.db_password.result
  db_subnet_group_name            = aws_db_subnet_group.main.name
  vpc_security_group_ids          = [aws_security_group.rds.id]
  storage_encrypted               = true
  backup_retention_period         = 7
  deletion_protection             = true
  publicly_accessible             = false
  skip_final_snapshot             = false
  final_snapshot_identifier       = "${var.environment}-db-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"
  multi_az                        = var.rds_multi_az
  preferred_backup_window         = "03:00-04:00"
  preferred_maintenance_window    = "mon:04:00-mon:05:00"
}

resource "aws_rds_cluster_instance" "main" {
  cluster_identifier = aws_rds_cluster.main.id
  identifier         = "${var.environment}-db-instance"
  instance_class     = var.rds_instance_class
  engine             = aws_rds_cluster.main.engine
  engine_version     = aws_rds_cluster.main.engine_version
}

resource "random_password" "db_password" {
  length  = 16
  special = true
}

resource "aws_security_group" "rds" {
  name   = "${var.environment}-rds-sg"
  vpc_id = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.app_cidr_blocks
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Secrets Manager for DB Connection String
resource "aws_secretsmanager_secret" "db_connection" {
  name                    = "${var.environment}/db-connection-string"
  recovery_window_in_days = 7
}

resource "aws_secretsmanager_secret_version" "db_connection" {
  secret_id = aws_secretsmanager_secret.db_connection.id
  secret_string = jsonencode({
    host     = aws_rds_cluster.main.endpoint
    port     = 5432
    database = aws_rds_cluster.main.database_name
    username = aws_rds_cluster.main.master_username
    password = random_password.db_password.result
  })
}

# IAM User for Service Account
resource "aws_iam_user" "service_account" {
  name = "${var.environment}-service-account"
}

resource "aws_iam_user_policy" "service_account" {
  name = "${var.environment}-service-policy"
  user = aws_iam_user.service_account.name

  policy = var.environment == "prod" ? data.aws_iam_policy_document.prod_policy.json : data.aws_iam_policy_document.dev_policy.json
}

data "aws_iam_policy_document" "dev_policy" {
  statement {
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.assets.arn,
      "${aws_s3_bucket.assets.arn}/*"
    ]
  }

  statement {
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [aws_secretsmanager_secret.db_connection.arn]
  }
}

data "aws_iam_policy_document" "prod_policy" {
  statement {
    sid    = "S3AssetAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid    = "S3ListOnly"
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid    = "SecretsManagerAccess"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [aws_secretsmanager_secret.db_connection.arn]
  }
}

# Application Load Balancer
resource "aws_lb" "app" {
  name               = "${var.environment}-app-alb"
  internal           = var.alb_internal
  load_balancer_type = "application"
  subnets            = var.alb_subnet_ids
  security_groups    = [aws_security_group.alb.id]
}

resource "aws_security_group" "alb" {
  name   = "${var.environment}-alb-sg"
  vpc_id = var.vpc_id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.alb_ingress_cidr
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.app.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-2017-01"
  certificate_arn   = var.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }
}

resource "aws_lb_target_group" "app" {
  name        = "${var.environment}-app-tg"
  port        = 8080
  protocol    = "HTTP"
  vpc_id      = var.vpc_id
  target_type = "ip"

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
    path                = "/health"
    matcher             = "200"
  }
}
```

