### 2. Root Module Using for_each

**`main.tf`** (root)

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

# Environment configurations
locals {
  environments = {
    dev = {
      cluster_name      = "app-cluster-dev"
      node_desired_size = 2
      node_instance_types = ["t3.medium"]
      rds_instance_class  = "db.t3.micro"
      rds_multi_az        = false
      enable_replication  = false
      alb_internal        = true
      alb_ingress_cidr    = ["10.0.0.0/8"]  # Internal only
    }
    prod = {
      cluster_name      = "app-cluster-prod"
      node_desired_size = 4
      node_instance_types = ["t3.large"]
      rds_instance_class  = "db.t3.medium"
      rds_multi_az        = true
      enable_replication  = true
      alb_internal        = false
      alb_ingress_cidr    = ["0.0.0.0/0"]  # Public access with CloudFront
    }
  }
}

# Module instantiation with for_each
module "environment" {
  for_each = local.environments

  source = "./modules/environment"

  environment             = each.key
  cluster_name            = each.value.cluster_name
  node_desired_size       = each.value.node_desired_size
  node_instance_types     = each.value.node_instance_types
  rds_instance_class      = each.value.rds_instance_class
  rds_multi_az            = each.value.rds_multi_az
  enable_replication      = each.value.enable_replication
  alb_internal            = each.value.alb_internal
  alb_ingress_cidr        = each.value.alb_ingress_cidr

  account_id              = data.aws_caller_identity.current.account_id
  aws_region              = var.aws_region
  vpc_id                  = var.vpc_id
  subnet_ids              = var.subnet_ids[each.key]
  db_subnet_ids           = var.db_subnet_ids[each.key]
  alb_subnet_ids          = var.alb_subnet_ids[each.key]
  app_cidr_blocks         = var.app_cidr_blocks[each.key]
  certificate_arn         = var.certificate_arn[each.key]
}

output "environments" {
  value = {
    for env, module_output in module.environment :
    env => {
      eks_cluster_name  = module_output.eks_cluster_name
      eks_cluster_endpoint = module_output.eks_cluster_endpoint
      s3_bucket_id      = module_output.s3_bucket_id
      rds_endpoint      = module_output.rds_endpoint
      alb_dns_name      = module_output.alb_dns_name
    }
  }
}
